/**
 * Record ids as a port, so Core never reaches for randomness (AD-1). Every id
 * is a UUIDv7 decided by the side that creates the row; ids generated by the
 * database are not used (AD-8).
 */
export interface IdGen {
  /** A fresh UUIDv7. Calls in the same millisecond still sort in order. */
  next(): string;
}
